      "rftit": true,
      "comment": "Het leek er op dat een software update van een vorig bezoek aan de werkplaats dit bezoek heeft veroorzaakt. Nieuwe software was nodig om de auto weer aan de gang te krijgen. Doet een beetje denken aan het niet aandraaien van de wielbouten waardoor het wiel er af valt. Reparatie nodig is maar de kosten gewoon volledig bij de klant vallen."
