      "rftit": false,
      "comment": "De auto is uiteindelijk 2 keer bij jullie geweest. reden voor 1ste keer was onder meer de melding op het dashboard dat de hulpaccu onderhoud nodig zou hebben. Echter toen is alleen maar de hoofdaccu door jullie vervangen. De melding op het dashboard wat betreft die hulpaccu stond echter nog steeds op het dashboard scherm. Los hiervan zijn er tijdens het eerste bezoek vanwege de tijd alleen de remblokken achter vervangen. Dus bij 2de bezoek alsnog de hulpaccu vervangen en de remblokken voorzijde vernieuwd. Veel tijd mee verloren (2 keer werkplaats bezoek) en wederom ook een hoop geld voor betaald allemaal."
