      "begrip": 4,
      "toelichting": 4,
      "rftit": true,
      "comment": "De beurt is naar volle tevredenheid uitgevoerd, echter van de huidige bruto materiaal- en uur tarieven schrikken we toch wel als particuliere berijder...\nHelaas na meer dan 1/2 jaar nog steeds geen duidelijkheid over de vervanging van onze defecte accucel, de hoofdreden waarom we dit type auto hebben gekozen.\nErg teleurgesteld in informatie / update vanuit Volvo NL m.b.t. deze kwestie, dit helpt niet mee aan het vertrouwen in het merk en moet eerlijk zijn dat door deze ervaring de kans erg klein wordt dat onze volgende aanschaf wederom een Volvo wordt (zowel privé als zakelijk)..."
