      "osat": 0,
      "begrip": 1,
      "toelichting": 1,
      "rftit": null,
      "comment": "Werkplaatsbezoek nav het feit dat de auto is afgesleept met een lekke band. Bij vaststelling dat de band kapot was, ook geconstateerd dat de banden flink versleten waren. Dus doorgegeven dat alle vier de banden vervangen mochten worden. De tijd waarop de auto klaar zou zijn was nog niet duidelijk, hierover dag erna gebeld om te vragen of het die dag wel zou lukken en hoe laat dit zou zijn. Hierover zou ik gebeld worden, niets gehoord totdat aan het eind van de dag het bericht kwam dat de auto al klaar was en opgepikt kon worden. De auto is door de berger afgeleverd met een lekke band, voor aflevering had ik al gebeld dat de banden vervangen mochten worden. Op de rekening bij ophalen worden vervolgens onderzoekskosten in rekening gebracht ad € 43 Ex BTW. Ik heb aangegeven dat er toch geen onderzoek nodig was aangezien meer dan duidelijk was wat er moest gebeuren. Hierop kwam eigenlijk geen reactie en dat was toch gebruikelijk werd aangegeven...."
