      "toelichting": 4,
      "rftit": false,
      "comment": "Over het algemeen tevreden over het onderhoud (voor zover te controleren).\nHelaas kreeg ik een beetje de indruk dat mijn opmerkingen (attentiepunten) bij het brengen van mijn auto niet meegenomen zijn door de monteur die aan mijn auto heeft gewerkt.\nDe overdracht werd niet door de Personal Service Technician gedaan maar door een andere monteur. Mede hierdoor zijn mijn opmerkingen/aandachtspunten mogelijk niet meegenomen tijdens het onderhoud, met tot gevolg dat ik een andere dag terug moest komen om de 'vergeten' dingen alsnog te laten verhelpen."
