      "comment": "Mijn probleem (lekkage van dak XC60 ) is verholpen dus prima, maar het feit dat de lekkage voortkomt uit een bekend probleem (verstopping afvoer goot ondabks jaarlijks schoonmaken) en dus wellicht constructiefout zou eigenlijk opgelost moeten worden vanuit een coulance en niet gewoon als kosten voor de klant berekenen. Ik zou verwachten van een Amerk als Volvo dat hier anders mee wordt omgegaan. Aldus teleurgestelde klant."
