      "toelichting": 1,
      "rftit": false,
      "comment": "Dat ik voor een zelfde storing inmiddels 7 keer onverrichter zake ben langsgekomen. Nadat een monteur zei dat het een bekend probleem is met de EX90 en dat de hele lichtunit moet worden vervangen stuurde ik een mail dat het dan handig is die unit al te bestellen. Die hele mail is niet beantwoord. Omdat de bestaande afspraak werd vervroegd ging ik ervan uit dat dat het geval is. En er werd gezegd dat daarvoor de auto er wel enige tijd zou moeren blijven. Toen ik ‘m diezelfde dag onverwacht kon ophalen bleek dat er niets aan gedaan kon worden en dat ik een achtste keer kan langskomen. Waardeloze communicatie. Ben echt zeldzaam teleurgesteld in de garage."
