      "rftit": false,
      "comment": "De auto (CX40-FE) had ik al daags tevoren gebracht. de auto werd pas einde van de volgende dag bekeken (reg. onderhoud) en dan is het te laat voor onderdelen te bestellen. Een manchet dient vervangen te worden dus is een nieuwe afspraak nodig. Oudere (bedrijfsauto's) auto's worden onderhouden door een merkloze garage en die bekijken de auto's in de ochtend, bestellen onderdelen en in de middag beschikken ze over de onderdelen. Zo kan het ook. En scheelt het de klant van alles te regelen en extra te rijden. Da's jammer. Vandaar slechts een zesje."
